import {demand,accepted,shortfall,purchasing,recordProblems,operationalKey} from './operations.js';
import {readinessIssues,overdueDays,localDateKey} from './manufacturing.js';
export const opsEscape=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const field=(k,label,v,type='text')=>`<label>${label}<input name="${k}" type="${type}" value="${opsEscape(v)}" ${type==='number'?'min="0" step="1"':''} maxlength="2000"></label>`;
export function operationalFields(p,lead=false,fullEditor=false){return `<p class="quantity-explainer">${accepted(p)} accepted · ${Math.max(0,p.quantity-accepted(p))} robot-required pieces missing · ${Math.max(0,demand(p)-(p.completedQty||0))} left to fabricate. Fabricated pieces await quality acceptance. Rework pieces are excluded from good pieces; scrap is discarded.</p>`+field('reworkQty','Current rework pieces (exclude from good count)',p.reworkQty||0,'number')+field('scrapQty','Scrapped pieces',p.scrapQty||0,'number')+(fullEditor?field('blockReason','Blocker reason',p.blockReason):'')+field('blockOwner','Blocker resolution owner',p.blockOwner)+field('blockNext','Blocker next action',p.blockNext)+field('blockExpected','Expected resolution',p.blockExpected,'date')+field('dependency','Dependency record ID / purchasing reference',p.dependency)+(lead?`<details class="advanced-fields full"><summary>Advanced production details</summary><div class="form-grid">${field('spareTarget','Optional spare target',p.spareTarget||0,'number')}${field('revision','Drawing / revision reference',p.revision)}${field('instructions','Setup / manufacturing instructions',p.instructions)}${field('location','Component storage location',p.location)}${field('shortCloseReason','Short-close reason (lead only, at least 5 characters)',p.shortCloseReason)}<label><input name="localOverride" type="checkbox" ${p.localOverride?'checked':''}> Keep local CAD metadata on BOM import</label></div><p>Production beyond required quantity is limited to the explicit spare target. Changing BOM-controlled fields without an override will be replaced at import.</p></details>`:'')+`<details class="part-history"><summary>Manufacturing details and history</summary><p>Internal ID: ${opsEscape(p.id)} · Revision: ${opsEscape(p.revision||'Not recorded')}</p><p>CAD/BOM identity: ${opsEscape(p.onshape?.key||'Manual record')}</p><p>Instructions: ${opsEscape(p.instructions||'Use reviewed drawing / dimensions')}</p><p>Location: ${opsEscape(p.location||'Not recorded')}</p><p>Blocked since: ${opsEscape(p.blockDate||'Not blocked')}</p><ul>${(p.history||[]).slice(-12).reverse().map(h=>'<li>'+opsEscape(h.label)+' · '+opsEscape(h.worker)+' · '+opsEscape(h.at)+'</li>').join('')}</ul></details>`;}
export function readOperationalFields(form,p){const out={};for(const k of ['blockReason','reworkQty','scrapQty','spareTarget','revision','instructions','location','shortCloseReason','blockOwner','blockNext','blockExpected','dependency'])if(form.elements[k])out[k]=['reworkQty','scrapQty','spareTarget'].includes(k)?Number(form.elements[k].value):operationalKey(form.elements[k].value);if(form.elements.localOverride)out.localOverride=form.elements.localOverride.checked;const next={...p,...out};if(next.blocked&&(!next.blockReason?.trim()||!next.blockOwner?.trim()||!next.blockNext?.trim()))throw Error('Add blocker reason, resolution owner and next action.');if(next.blocked&&!p.blocked)out.blockDate=localDateKey();return out;}
export function queueList(parts){return `<div class="queue-list">${parts.map(p=>`<article class="queue-row ${overdueDays(p)?'is-overdue':''}"><label><input type="checkbox" data-bulk-id="${opsEscape(p.id)}" aria-label="Select ${opsEscape(p.name)}"></label><button data-edit="${opsEscape(p.id)}" class="part-name">${opsEscape(p.number)} · ${opsEscape(p.name)}</button><span>${opsEscape(p.status)} · ${opsEscape(p.owner||p.assignedTo||'Unassigned')} · ${opsEscape(p.process||'No process')}</span><span>${accepted(p)} accepted / ${p.quantity} required · ${Math.max(0,demand(p)-(p.completedQty||0))} to fabricate</span><span>${overdueDays(p)?'Overdue: ':''}${opsEscape(p.due||'No due date')} · ${opsEscape(p.priority)}</span>${p.blocked?'<p class="shop-note">Blocked: '+opsEscape(p.blockReason)+' · '+opsEscape(p.blockOwner||'Owner needed')+' · '+opsEscape(p.blockNext||'Next action needed')+'</p>':''}${readinessIssues(p).length&&p.status!=='Finished'?'<p>'+opsEscape(readinessIssues(p).join(' '))+'</p>':''}</article>`).join('')}</div>`;}
export function readinessOverview(w){const names=[...new Set([...w.parts,...w.cots].map(p=>p.subsystem||'Unassigned subsystem'))].sort();return `<p class="helper">Tracks only records entered in this project. Quantities measure components, not remaining labor or complete robot / competition readiness.</p><div class="project-grid">${names.map(name=>{const parts=w.parts.filter(p=>(p.subsystem||'Unassigned subsystem')===name),items=w.cots.filter(p=>(p.subsystem||'Unassigned subsystem')===name);return `<section class="project-tile"><h2>${opsEscape(name)}</h2><p>${parts.reduce((n,p)=>n+shortfall(p),0)} manufactured robot pieces still needed</p><p>${items.reduce((n,i)=>n+purchasing(i).missing,0)} purchased pieces missing</p><p>${parts.filter(p=>p.blocked).length} unresolved blockers</p><p>${parts.reduce((n,p)=>n+Math.max(0,(p.completedQty||0)-accepted(p)),0)} fabricated pieces awaiting acceptance</p><p>${parts.reduce((n,p)=>n+Math.max(0,(p.spareTarget||0)-Math.max(0,accepted(p)-p.quantity)),0)} spare shortage</p><details><summary>Components and locations</summary>${[...parts,...items].map(p=>'<p>'+opsEscape(p.number)+' · '+opsEscape(p.name)+' · '+opsEscape(p.location||'Location not recorded')+'</p>').join('')}</details></section>`;}).join('')}</div><h2>Records to review</h2><p>No records are automatically deleted.</p><div class="admin-parts">${w.parts.filter(p=>recordProblems(p).length).map(p=>'<button class="admin-part" data-overview-edit="'+opsEscape(p.id)+'">'+opsEscape(p.number)+' · '+opsEscape(p.name)+'<span>'+opsEscape(recordProblems(p).join('; '))+'</span></button>').join('')||'<p>No record warnings.</p>'}</div>`;}
export function operationalExport(w,kind){if(kind==='purchase'||kind==='receiving')return [['Part','SKU','Vendor','Required pieces','Stock available','Ordered pieces','Inbound pieces','Received pieces','Pieces to order','Packs to order','Pack size','Shortfall','Order reference','Expected','Location'],...w.cots.filter(i=>kind==='purchase'?purchasing(i).order>0:purchasing(i).inbound>0).map(i=>{const q=purchasing(i);return [i.name,i.number,i.vendor,i.needed,q.stock,i.ordered,q.inbound,i.received,q.order,q.packs,i.packSize,q.missing,i.reference,i.eta,i.location];})];return [['Part','Number','Subsystem','Required','Accepted','Fabricated good','Remaining robot demand','Spare target','Spare shortfall','Rework','Scrap','Stage','Worker','Process','Due','Blocker','Resolver','Next action','Location','Revision','CAD'],...w.parts.filter(p=>kind!=='spares'||p.spareTarget>0||accepted(p)>p.quantity).map(p=>[p.name,p.number,p.subsystem,p.quantity,accepted(p),p.completedQty,shortfall(p),p.spareTarget,Math.max(0,(p.spareTarget||0)-Math.max(0,accepted(p)-p.quantity)),p.reworkQty,p.scrapQty,p.status,p.owner||p.assignedTo,p.process,p.due,p.blockReason,p.blockOwner,p.blockNext,p.location,p.revision,p.cad])];}
